<?php $pageTitle='Submissions';$active='submissions';require_once __DIR__.'/../includes/auth.php';require_role('teacher');require_once __DIR__.'/../includes/ui.php';$teacherId=(int)user()['id'];$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$sid=(int)$_POST['submission_id'];$marks=$_POST['marks']===''?null:(float)$_POST['marks'];$feedback=trim($_POST['feedback']??'');$st=$pdo->prepare('SELECT s.id,s.student_id,a.max_marks,a.title FROM submissions s JOIN assignments a ON a.id=s.assignment_id JOIN courses c ON c.id=a.course_id WHERE s.id=? AND c.teacher_id=?');$st->execute([$sid,$teacherId]);$row=$st->fetch();if(!$row)throw new RuntimeException('Submission not found.');if($marks!==null && ($marks<0||$marks>$row['max_marks']))throw new RuntimeException('Marks must be between 0 and '.$row['max_marks'].'.');$pdo->prepare("UPDATE submissions SET marks=?,feedback=?,graded_at=NOW(),status='graded' WHERE id=?")->execute([$marks,$feedback,$sid]);add_notification((int)$row['student_id'],'Assignment graded','Your submission for '.$row['title'].' has been graded.');flash('success','Submission graded.');}catch(Throwable $e){$error=$e->getMessage();}}
$filter=(int)($_GET['assignment_id']??0);$sql="SELECT s.*,u.full_name student,u.email,a.title assignment_title,a.max_marks,c.title course_title FROM submissions s JOIN users u ON u.id=s.student_id JOIN assignments a ON a.id=s.assignment_id JOIN courses c ON c.id=a.course_id WHERE c.teacher_id=?";$params=[$teacherId];if($filter){$sql.=' AND a.id=?';$params[]=$filter;}$sql.=' ORDER BY s.submitted_at DESC';$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();include __DIR__.'/../includes/app_start.php';?>
<div class="page-header"><div><div class="section-kicker mb-2">Assessment review</div><h1>Submissions</h1><p>Review student work and record marks and feedback.</p></div></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="card p-0 overflow-hidden"><div class="table-responsive border-0"><table class="table"><thead><tr><th class="ps-4">Student</th><th>Assignment</th><th>Course</th><th>Submitted</th><th>Status</th><th>Marks</th><th class="pe-4">Grade</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td class="ps-4"><div class="fw-semibold"><?=e($r['student'])?></div><div class="small text-muted"><?=e($r['email'])?></div></td><td><?=e($r['assignment_title'])?></td><td><?=e($r['course_title'])?></td><td><?=e($r['submitted_at']?date('d M Y, h:i A',strtotime($r['submitted_at'])):'—')?></td><td><?=badgeSoft(ucfirst($r['status']),$r['status']==='graded'?'success':'warning')?></td><td><?=e($r['marks']!==null?(string)$r['marks'].' / '.$r['max_marks']:'Pending')?></td><td class="pe-4"><form method="post" class="d-flex gap-1 align-items-center"><?=csrf_input()?><input type="hidden" name="submission_id" value="<?=$r['id']?>"><input name="marks" class="form-control form-control-sm" style="width:82px" type="number" step="0.01" min="0" max="<?=$r['max_marks']?>" value="<?=e($r['marks']??'')?>" placeholder="marks"><input name="feedback" class="form-control form-control-sm" style="width:180px" value="<?=e($r['feedback']??'')?>" placeholder="Feedback"><button class="btn btn-sm btn-primary">Save</button><?php if($r['file_path']):?><a class="btn btn-sm btn-light" href="../<?=e($r['file_path'])?>" target="_blank">File</a><?php endif;?></form></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><div class="empty-state"><div class="icon"><i class="bi bi-inbox"></i></div><h5>No submissions</h5></div><?php endif;?></div>
<?php include __DIR__.'/../includes/app_end.php'; ?>
